function usePersistentState(key, initial){
  const [value,setValue] = useState(()=>{
    try{const raw=localStorage.getItem(key); return raw?JSON.parse(raw):initial}catch{return initial}
  });
  useEffect(()=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}},[key,value]);
  return [value,setValue];
}

function App(){
  const [lang,setLang]=usePersistentState('lb_lang','en');
  const [cart,setCart]=usePersistentState('lb_cart',[]);
  const [orders,setOrders]=usePersistentState('lb_orders',[]);
  const [vendors,setVendors]=usePersistentState('lb_vendors',seedVendors);
  const [role,setRole]=usePersistentState('lb_role','customer');
  const [toast,setToast]=useState('');
  const t=translations[lang];
  const notify=(m)=>{setToast(m); setTimeout(()=>setToast(''),2200)};
  const addToCart=(vendor,item)=>{
    setCart(prev=>{
      if(prev.length && prev[0].vendor.id!==vendor.id){
        notify(`Your cart has items from ${prev[0].vendor.name}. Clear the cart before ordering here.`);
        return prev;
      }
      const found=prev.find(x=>x.item.id===item.id && x.vendor.id===vendor.id);
      if(found) return prev.map(x=>x.item.id===item.id&&x.vendor.id===vendor.id?{...x,qty:x.qty+1}:x);
      return [...prev,{vendor,item,qty:1}]
    });
    if(!cart.length || cart[0]?.vendor.id===vendor.id) notify(`${item.name} added to cart`);
  };
  const clearCart=()=>setCart([]);
  return <>
    <Header lang={lang} setLang={setLang} role={role} setRole={(r)=>{setRole(r);notify(`Switched to ${r}`)}} cart={cart} />
    <Routes>
      <Route path="/" element={<Home t={t} vendors={vendors}/>}/>
      <Route path="/explore" element={<Explore t={t} vendors={vendors} addToCart={addToCart}/>}/>
      <Route path="/vendor/:id" element={<VendorPage t={t} vendors={vendors} addToCart={addToCart}/>}/>
      <Route path="/cart" element={<CartPage t={t} cart={cart} setCart={setCart} onClear={clearCart} orders={orders} setOrders={setOrders} notify={notify}/>}/>
      <Route path="/orders" element={<CustomerOrders t={t} orders={orders} />}/>
      <Route path="/orders/:orderId" element={<OrderDetailPage orders={orders}/>}/>
      <Route path="/account" element={<AccountPage notify={notify}/>}/>
      <Route path="/favorites" element={<FavoritesPage vendors={vendors}/>}/>
      <Route path="/login" element={<AuthPage role={role} setRole={setRole} notify={notify}/>}/>
      <Route path="/onboard" element={<OnboardPro t={t} setVendors={setVendors} notify={notify}/>}/>
      <Route path="/vendor-dashboard/*" element={<VendorDashboard t={t} vendors={vendors} setVendors={setVendors} orders={orders} setOrders={setOrders} notify={notify}/>}/>
      <Route path="/admin" element={<AdminPagePro t={t} vendors={vendors} orders={orders}/>}/>
      <Route path="/scan/:id" element={<ScanExperience t={t} vendors={vendors} addToCart={addToCart}/>}/>
      <Route path="/features" element={<FeaturesPage/>}/>
      <Route path="/pricing" element={<PricingPage/>}/>
      <Route path="/how-it-works" element={<HowItWorksPage/>}/>
      <Route path="/faq" element={<FAQPage/>}/>
      <Route path="/about" element={<AboutPage/>}/>
      <Route path="/contact" element={<ContactPage/>}/>
      <Route path="/privacy" element={<LegalPage type="privacy"/>}/>
      <Route path="/terms" element={<LegalPage type="terms"/>}/>
      <Route path="/refund-policy" element={<LegalPage type="refund"/>}/>
      <Route path="/support" element={<SupportPage/>}/>
      <Route path="/for-customers" element={<SolutionPage kind="customers"/>}/>
      <Route path="/for-vendors" element={<SolutionPage kind="vendors"/>}/>
      <Route path="/restaurant-solutions" element={<SolutionPage kind="restaurants"/>}/>
      <Route path="/qr-ordering" element={<SolutionPage kind="qr"/>}/>
      <Route path="/table-ordering" element={<SolutionPage kind="table"/>}/>
      <Route path="/careers" element={<SolutionPage kind="careers"/>}/>
      <Route path="/blog" element={<SolutionPage kind="blog"/>}/>
      <Route path="/cookie-policy" element={<LegalPage type="cookie"/>}/>
      <Route path="/community-guidelines" element={<LegalPage type="community"/>}/>
      <Route path="*" element={<NotFoundPage/>}/>
    </Routes>
    <SiteFooter/>
    {toast && <div className="toast">{toast}</div>}
  </>
}

function Header({lang,setLang,role,setRole,cart}){
  const t=translations[lang];
  const [open,setOpen]=useState(false); const [mobileOpen,setMobileOpen]=useState(false);
  return <header className="topbar">
    <div className="brand"><Link to="/"><span className="brandMark">LB</span><span>Local<span>Bite</span></span></Link></div>
    <nav className="desktopNav"><Link to="/explore">{t.explore}</Link><Link to="/features">Features</Link><Link to="/pricing">Pricing</Link><Link to="/orders">{t.orders}</Link><Link to="/onboard">{t.business}</Link></nav>
    <div className="topActions">
      <button className="iconBtn" onClick={()=>setLang(lang==='en'?'hi':'en')} title="Language"><Globe2 size={18}/><span>{lang==='en'?'HI':'EN'}</span></button>
      <Link className="iconBtn cartBtn" to="/cart"><ShoppingCart size={19}/><b>{cart.reduce((n,x)=>n+x.qty,0)}</b></Link>
      <button className="mobileMenuBtn iconBtn" aria-label="Open navigation" onClick={()=>setMobileOpen(!mobileOpen)}><Menu size={18}/></button>
      <button className="roleBtn" onClick={()=>setOpen(!open)}><User size={16}/>{role}<ChevronDown size={15}/></button>
      {mobileOpen && <div className="mobileNav"><Link to="/explore" onClick={()=>setMobileOpen(false)}>Explore</Link><Link to="/features" onClick={()=>setMobileOpen(false)}>Features</Link><Link to="/pricing" onClick={()=>setMobileOpen(false)}>Pricing</Link><Link to="/orders" onClick={()=>setMobileOpen(false)}>Orders</Link><Link to="/onboard" onClick={()=>setMobileOpen(false)}>Add my shop</Link></div>}
      {open && <div className="roleMenu">{['customer','vendor','admin'].map(r=><button key={r} onClick={()=>{setRole(r);setOpen(false)}}>{r}</button>)}<Link to={role==='vendor'?'/vendor-dashboard':role==='admin'?'/admin':'/'} onClick={()=>setOpen(false)}>Open workspace</Link></div>}
    </div>
  </header>
}

